1	/**
2	 * native-tool-overrides
3	 *
4	 * Registers Luke's native tools by wrapping Pi's lowercase tool factories and overriding
5	 * their behavior — Edit argument repair, Bash timeout-to-background, deferred loading,
6	 * and Claude-style UI labels ("Read"/"Bash"/...) via ToolDefinition.label while keeping
7	 * upstream lowercase wire names (read/edit/write/grep/find/ls/bash). Also owns the
8	 * web_fetch/web_search marker tools (claude-bridge native server tools that throw on
9	 * local execute). This is more than aliasing: it is the override layer that keeps
10	 * custom tool behavior out of pi-mono-fork core.
11	 *
12	 * Lifts these tool definitions out of pi-mono-fork core so the fork can stay closer
13	 * to upstream Pi. The hardcoded tool-name references in `agent-session.ts` and `sdk.ts`
14	 * (defaultActiveToolNames, CLAUDE_BRIDGE_NATIVE_TOOL_NAMES) resolve to these
15	 * extension-provided tools at session startup via the runtime tool registry.
16	 *
17	 * Naming: lowercase wire names match core factories (so the extension tool overwrites
18	 * the core builtin by registry key and the bridge presents CC-canonical casing); UI
19	 * display comes from `label`. High-traffic edit/shell/read tools are always loaded;
20	 * utility tools stay provider-native deferred so they are available without billing
21	 * their full schemas every turn. Agent stays capitalized (core filters an extension
22	 * tool named "agent" when the core "agent" builtin exists).
23	 */
24	
25	import {
26	  AGENTS_ENGINE_SERVICE_ID,
27	  BASH_BG_JOBS_SERVICE_ID,
28	  type AgentEngine,
29	  type BashBgJobStore,
30	  createBashBgJobStore,
31	  createBashToolDefinition,
32	  createEditToolDefinition,
33	  createFindToolDefinition,
34	  createGrepToolDefinition,
35	  createLsToolDefinition,
36	  createReadToolDefinition,
37	  createTaskListToolDefinition,
38	  createTaskOutputToolDefinition,
39	  createTaskStopToolDefinition,
40	  createUppercaseAgentToolDefinition,
41	  createWriteToolDefinition,
42	  type ExtensionAPI,
43	  onBashTimeout,
44	} from "@valkyriweb/pi-coding-agent";
45	import { Container, Text } from "@valkyriweb/pi-tui";
46	import { type Static, Type } from "typebox";
47	import { readFileSync } from "node:fs";
48	import { homedir } from "node:os";
49	import { join, resolve } from "node:path";
50	
51	// --- Per-profile tool selection (include / exclude) ----------------------------
52	//
53	// Lets a profile register only a subset of the canonical native tools without
54	// forking this extension. Resolution order (first wins per field):
55	//   1. env: PI_NATIVE_TOOL_INCLUDE / PI_NATIVE_TOOL_EXCLUDE (comma-separated)
56	//   2. settings.json: extensions.native-tool-overrides.{include,exclude}
57	//   3. defaults (register everything)
58	//
59	// `include` is an allowlist (only these register). `exclude` is a denylist
60	// (everything except these). If both resolve, include is applied first, then
61	// exclude removes from it. Names match the capability case-insensitively
62	// (e.g. "Agent", "agent" both exclude the Agent alias).
63	//
64	// CACHE CRITICAL: this is read once at load and gates which schemas enter the
65	// stable first-turn tools[] set. It must be deterministic per process; never
66	// derive it from per-turn state.
67	interface NativeToolSelection {
68	  include: Set<string> | null;
69	  exclude: Set<string>;
70	}
71	
72	function parseNameList(raw: unknown): string[] {
73	  if (typeof raw === "string") return raw.split(",").map((s) => s.trim()).filter(Boolean);
74	  if (Array.isArray(raw)) return raw.filter((s): s is string => typeof s === "string").map((s) => s.trim()).filter(Boolean);
75	  return [];
76	}
77	
78	function loadSelection(): NativeToolSelection {
79	  let includeNames = parseNameList(process.env.PI_NATIVE_TOOL_INCLUDE);
80	  let excludeNames = parseNameList(process.env.PI_NATIVE_TOOL_EXCLUDE);
81	
82	  if (includeNames.length === 0 || excludeNames.length === 0) {
83	    const path = join(process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
84	    try {
85	      const raw = readFileSync(path, "utf8");
86	      const parsed = JSON.parse(raw) as {
87	        extensions?: { "native-tool-overrides"?: { include?: unknown; exclude?: unknown } };
88	      };
89	      const cfg = parsed.extensions?.["native-tool-overrides"];
90	      if (includeNames.length === 0) includeNames = parseNameList(cfg?.include);
91	      if (excludeNames.length === 0) excludeNames = parseNameList(cfg?.exclude);
92	    } catch {
93	      // No settings.json / unreadable — fall back to env + defaults.
94	    }
95	  }
96	
97	  const norm = (s: string) => s.toLowerCase();
98	  return {
99	    include: includeNames.length > 0 ? new Set(includeNames.map(norm)) : null,
100	    exclude: new Set(excludeNames.map(norm)),
101	  };
102	}
103	
104	function makeIsEnabled(selection: NativeToolSelection): (name: string) => boolean {
105	  return (name: string) => {
106	    const key = name.toLowerCase();
107	    if (selection.include && !selection.include.has(key)) return false;
108	    if (selection.exclude.has(key)) return false;
109	    return true;
110	  };
111	}
112	
113	// --- Edit-tool argument repair (fork-local, kept out of pi core) ----------------
114	//
115	// Some models cram extra replacements onto one Edit call as numbered siblings
116	// (oldText2/newText2, oldText3/newText3, ...) instead of using the edits[] array.
117	// The core Edit schema is additionalProperties:false, so those calls hard-reject.
118	// Upstream already folds a single top-level oldText/newText pair; we extend that
119	// to numbered siblings here rather than patching core, so pi-mono-fork stays at
120	// upstream shape. We normalize the numbered pairs into edits[], then delegate to
121	// the upstream prepareArguments for its JSON-string + single-pair handling.
122	type EditReplacement = { oldText: string; newText: string };
123	
124	function foldNumberedEditPairs(input: unknown): unknown {
125	  if (!input || typeof input !== "object") return input;
126	  const args = input as Record<string, unknown>;
127	  const pairs: EditReplacement[] = [];
128	  const consumed = new Set<string>();
129	  if (typeof args.oldText === "string" && typeof args.newText === "string") {
130	    pairs.push({ oldText: args.oldText, newText: args.newText });
131	    consumed.add("oldText").add("newText");
132	  }
133	  for (let n = 2; ; n++) {
134	    const oldKey = `oldText${n}`;
135	    const newKey = `newText${n}`;
136	    if (typeof args[oldKey] !== "string" || typeof args[newKey] !== "string") break;
137	    pairs.push({ oldText: args[oldKey] as string, newText: args[newKey] as string });
138	    consumed.add(oldKey).add(newKey);
139	  }
140	  if (pairs.length === 0) return input;
141	  const existing = Array.isArray(args.edits) ? (args.edits as EditReplacement[]) : [];
142	  const rest = Object.fromEntries(Object.entries(args).filter(([key]) => !consumed.has(key)));
143	  return { ...rest, edits: [...existing, ...pairs] };
144	}
145	
146	function withNumberedEditRepair<T extends { prepareArguments?: (input: unknown) => unknown }>(definition: T): T {
147	  const upstreamPrepare = definition.prepareArguments;
148	  return {
149	    ...definition,
150	    prepareArguments: (input: unknown) => {
151	      const folded = foldNumberedEditPairs(input);
152	      return upstreamPrepare ? upstreamPrepare(folded) : folded;
153	    },
154	  };
155	}
156	
157	// --- Pi-native tools (upstream-aligned lowercase names, capitalized UI labels) ---
158	// Names match core's lowercase factories (read/edit/write/grep/find/ls/bash) so the
159	// extension tool overwrites the core builtin by registry key and the bridge presents
160	// CC-canonical casing on the wire. Display stays "Read"/"Bash"/... via ToolDefinition
161	// .label. Agent stays capitalized (core filters an extension tool named "agent" when
162	// the core "agent" builtin exists); TaskOutput/TaskStop/TaskList are CC-canonical names
163	// with no lowercase upstream form.
164	
165	const LOAD_HOOK = "load";
166	const NATIVE_TOOL_NAMES = [
167	  "read",
168	  "bash",
169	  "TaskOutput",
170	  "TaskStop",
171	  "TaskList",
172	  "edit",
173	  "write",
174	  "Agent",
175	  "grep",
176	  "find",
177	  "ls",
178	] as const;
179	
180	// Core's Bash tool blocks `cd <cwd> && ...` with a "Blocked redundant cd" error to
181	// steer toward native tools / `-C` flags. Luke wants those to just run instead of
182	// erroring. We strip a leading redundant `cd <cwd>` (one that resolves to the session
183	// cwd) before core's guard sees the command, so it executes in cwd as intended. A cd
184	// to a *different* directory is left untouched (core already allows that). Done in the
185	// extension wrapper's prepareArguments so pi-mono-fork core stays at upstream shape.
186	const REDUNDANT_CD_PREFIX = /^(\s*cd\s+("[^"]+"|'[^']+'|(?:\\\S|\S)+)\s*(?:&&|;)\s*)(?=\S)/s;
187	function unquoteShellPath(value: string): string {
188	  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
189	    return value.slice(1, -1);
190	  }
191	  return value.replace(/\\ /g, " ");
192	}
193	export function stripRedundantCd(command: string, cwd: string): string {
194	  const match = REDUNDANT_CD_PREFIX.exec(command);
195	  if (!match) return command;
196	  let target = unquoteShellPath(match[2]!);
197	  if (target === "~" || target.startsWith("~/")) target = join(homedir(), target.slice(2));
198	  if (resolve(cwd, target) !== resolve(cwd)) return command;
199	  return command.slice(match[1]!.length);
200	}
201	
202	function registerCanonicalNativeTools(pi: ExtensionAPI, isEnabled: (name: string) => boolean) {
203	  const cwd = process.cwd();
204	  const jobs = createBashBgJobStore();
205	  const agentOptions = { getEngine: () => pi.harness.use<AgentEngine>(AGENTS_ENGINE_SERVICE_ID) };
206	
207	  pi.harness.provide<BashBgJobStore>(BASH_BG_JOBS_SERVICE_ID, jobs, { scope: "process", replace: true });
208	
209	  // Register helper: skip tools the active profile selection excludes.
210	  const add = (name: string, definition: object) => {
211	    if (!isEnabled(name)) return;
212	    pi.registerTool(definition as Parameters<typeof pi.registerTool>[0]);
213	  };
214	
215	  // CACHE CRITICAL: this extension owns the stable first-turn native tool
216	  // schema set for Luke's Pi profile. Keep this list deterministic and one
217	  // schema per capability. Dynamic tool decisions belong in tool-search, not
218	  // in this startup alias layer.
219	  add("read", {
220	    ...createReadToolDefinition(cwd, { label: "Read" }),
221	    alwaysLoad: true,
222	    replacesBuiltins: ["read"],
223	  });
224	  // Rewrite the bash_output/bash_kill mentions in core's Bash description to the
225	  // unified task_id tools this profile actually ships (TaskOutput/TaskStop).
226	  const bashDef = createBashToolDefinition(cwd, { label: "Bash" });
227	  add("bash", {
228	    ...bashDef,
229	    description: bashDef.description
230	      ?.replace(/bash_output\(bgId\)/g, "TaskOutput(task_id)")
231	      .replace(/bash_kill\(bgId\)/g, "TaskStop(task_id)"),
232	    // Strip a redundant leading `cd <cwd> &&` so it runs instead of hitting core's
233	    // "Blocked redundant cd" guard. Delegates to any upstream prepareArguments first.
234	    prepareArguments: (input: unknown) => {
235	      const args = (bashDef.prepareArguments ? bashDef.prepareArguments(input) : input) as
236	        | { command?: unknown }
237	        | undefined;
238	      if (args && typeof args.command === "string") {
239	        return { ...args, command: stripRedundantCd(args.command, cwd) };
240	      }
241	      return args;
242	    },
243	    alwaysLoad: true,
244	    // Core ships BOTH lowercase `bash` and capitalized `Bash` builtins; replace both
245	    // so this single lowercase `bash` is the only bash schema (no duplicate).
246	    replacesBuiltins: ["bash", "Bash"],
247	  });
248	  // Detach-on-timeout is Luke's opinion, not core's. The fork keeps a neutral
249	  // default (kill + report timeout); here we opt the Bash tool into Claude
250	  // Code-style auto-background: a timed-out command keeps running as a bg job,
251	  // readable via TaskOutput and stoppable via TaskStop. `t.background()` adopts
252	  // the live process into the same bg registry these tools already read.
253	  //
254	  // Install once as a process-wide preference and NEVER restore it on session
255	  // dispose. `onBashTimeout` mutates a single package-global resolver, and its
256	  // restore fns are not a real stack — restoring on every top-level dispose
257	  // (/new, /fork, switchSession) reverted the global to the core kill policy,
258	  // so a timed-out command was KILLED instead of detached until the next session
259	  // re-activated this extension (and stacked disposes clobbered it to kill
260	  // outright). The policy is idempotent — always the same detach closure — so
261	  // re-installing on each activation and never restoring keeps auto-background
262	  // reliably on. Regression: autobg-lifecycle.test.mjs.
263	  if (isEnabled("bash")) {
264	    onBashTimeout((t) => ({ backgroundedJobId: t.background().id }));
265	  }
266	  // CACHE CRITICAL: these utility aliases must remain provider-visible but
267	  // schema-deferred. Marking them alwaysLoad reintroduces the prompt-cache burst
268	  // where background/listing schemas are billed every turn. They are discovered
269	  // through the stable <deferred-tools> index and loaded through Anthropic
270	  // `defer_loading` / `tool_reference`, matching Claude Code and Codex.
271	  // Unified background-task tools (Claude Code task_id parity) over the core
272	  // task-registry seam: one id space across background bash jobs AND background
273	  // agent runs. These replace the bash-only BashOutput/KillShell. The bash log
274	  // rendering (tail/head/all, status header) is preserved inside TaskOutput.
275	  add("TaskOutput", {
276	    ...createTaskOutputToolDefinition(),
277	    deferLoading: true,
278	    replacesBuiltins: ["bash_output"],
279	  });
280	  add("TaskStop", {
281	    ...createTaskStopToolDefinition(),
282	    deferLoading: true,
283	    replacesBuiltins: ["bash_kill"],
284	  });
285	  add("TaskList", {
286	    ...createTaskListToolDefinition(),
287	    deferLoading: true,
288	  });
289	  add("edit", {
290	    ...withNumberedEditRepair(createEditToolDefinition(cwd, { label: "Edit" })),
291	    alwaysLoad: true,
292	    replacesBuiltins: ["edit"],
293	  });
294	  add("write", {
295	    ...createWriteToolDefinition(cwd, { label: "Write" }),
296	    alwaysLoad: true,
297	    replacesBuiltins: ["write"],
298	  });
299	  add("Agent", {
300	    ...createUppercaseAgentToolDefinition("", agentOptions),
301	    alwaysLoad: true,
302	  });
303	  add("grep", {
304	    ...createGrepToolDefinition(cwd, { label: "Grep" }),
305	    alwaysLoad: true,
306	    replacesBuiltins: ["grep"],
307	  });
308	  add("find", {
309	    ...createFindToolDefinition(cwd, { label: "Find" }),
310	    deferLoading: true,
311	    replacesBuiltins: ["find"],
312	  });
313	  add("ls", {
314	    ...createLsToolDefinition(cwd, { label: "Ls" }),
315	    deferLoading: true,
316	    replacesBuiltins: ["ls"],
317	  });
318	
319	  pi.onSessionDispose(() => {
320	    jobs.killAll();
321	  });
322	}
323	
324	// --- WebFetch / WebSearch marker tools -----------------------------------------
325	//
326	// These are native Anthropic/Claude server tools. The provider intercepts the
327	// tool call before local execute(); local execute() never legitimately runs.
328	
329	const webFetchSchema = Type.Object({
330	  allowed_domains: Type.Optional(Type.Array(Type.String({ description: "Only allow fetching from these domains" }))),
331	  blocked_domains: Type.Optional(Type.Array(Type.String({ description: "Never fetch from these domains" }))),
332	  max_content_tokens: Type.Optional(
333	    Type.Number({ description: "Approximate maximum tokens used for fetched web page text content" }),
334	  ),
335	  use_cache: Type.Optional(
336	    Type.Boolean({
337	      description:
338	        "Whether to use cached content. Set false only when the user explicitly requests fresh content or rapidly-changing sources.",
339	    }),
340	  ),
341	});
342	
343	type WebFetchInput = Static<typeof webFetchSchema>;
344	
345	const webSearchSchema = Type.Object({
346	  query: Type.String({ description: "Search query" }),
347	  allowed_domains: Type.Optional(Type.Array(Type.String({ description: "Only allow results from these domains" }))),
348	  blocked_domains: Type.Optional(Type.Array(Type.String({ description: "Never return results from these domains" }))),
349	});
350	
351	type WebSearchInput = Static<typeof webSearchSchema>;
352	
353	const WEBFETCH_UNSUPPORTED = "WebFetch is only available with the claude-bridge provider";
354	const WEBFETCH_LOCAL = "WebFetch is a native Anthropic/Claude provider tool and should not execute locally";
355	const WEBSEARCH_UNSUPPORTED = "WebSearch is only available with the claude-bridge provider";
356	const WEBSEARCH_LOCAL = "WebSearch is a native Anthropic/Claude provider tool and should not execute locally";
357	
358	function normalizeWebFetchInput(args: unknown): WebFetchInput {
359	  return args && typeof args === "object" ? (args as WebFetchInput) : {};
360	}
361	
362	function normalizeWebSearchInput(args: unknown): WebSearchInput {
363	  const input = args && typeof args === "object" ? (args as WebSearchInput) : ({ query: "" } as WebSearchInput);
364	  if (input.allowed_domains?.length && input.blocked_domains?.length) {
365	    throw new Error("WebSearch accepts either allowed_domains or blocked_domains, not both");
366	  }
367	  return input;
368	}
369	
370	function registerWebFetch(pi: ExtensionAPI, isEnabled: (name: string) => boolean) {
371	  // LLM/wire name is the Anthropic-native `web_fetch`; TUI displays "WebFetch" via label.
372	  if (!isEnabled("web_fetch")) return;
373	  pi.registerTool({
374	    name: "web_fetch",
375	    deferLoading: true,
376	    label: "WebFetch",
377	    description:
378	      "Fetch web page content using Anthropic/Claude's native web_fetch server tool. Only available for claude-bridge models.",
379	    promptSnippet: "Fetch web page content using Anthropic/Claude's native web_fetch server tool.",
380	    providers: ["claude-bridge"],
381	    parameters: webFetchSchema,
382	    prepareArguments: normalizeWebFetchInput,
383	    async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
384	      if (ctx.model?.provider !== "claude-bridge") throw new Error(WEBFETCH_UNSUPPORTED);
385	      throw new Error(WEBFETCH_LOCAL);
386	    },
387	    renderCall(args, theme) {
388	      const opts: string[] = [];
389	      if (args?.allowed_domains?.length) opts.push(`allow ${args.allowed_domains.join(", ")}`);
390	      if (args?.blocked_domains?.length) opts.push(`block ${args.blocked_domains.join(", ")}`);
391	      if (args?.use_cache === false) opts.push("fresh");
392	      const suffix = opts.length ? ` ${theme.fg("toolOutput", `(${opts.join("; ")})`)}` : "";
393	      return new Text(`${theme.fg("toolTitle", theme.bold("WebFetch"))}${suffix}`, 0, 0);
394	    },
395	    renderResult(result, { expanded }, theme) {
396	      if (!expanded) return new Container();
397	      const block = result.content.find((item) => item.type === "text");
398	      const text = block?.type === "text" ? block.text : "(no output)";
399	      return new Text(theme.fg("dim", text), 0, 0);
400	    },
401	  });
402	}
403	
404	function registerWebSearch(pi: ExtensionAPI, isEnabled: (name: string) => boolean) {
405	  // LLM/wire name is the Anthropic-native `web_search`; TUI displays "WebSearch" via label.
406	  if (!isEnabled("web_search")) return;
407	  pi.registerTool({
408	    name: "web_search",
409	    deferLoading: true,
410	    label: "WebSearch",
411	    description:
412	      "Search the web using Anthropic/Claude's native web_search server tool. Only available for claude-bridge models.",
413	    promptSnippet: "Search the web using Anthropic/Claude's native web_search server tool.",
414	    providers: ["claude-bridge"],
415	    parameters: webSearchSchema,
416	    prepareArguments: normalizeWebSearchInput,
417	    async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
418	      if (ctx.model?.provider !== "claude-bridge") throw new Error(WEBSEARCH_UNSUPPORTED);
419	      throw new Error(WEBSEARCH_LOCAL);
420	    },
421	    renderCall(args, theme) {
422	      const query = typeof args?.query === "string" ? args.query : "";
423	      const shown = query.length > 90 ? `${query.slice(0, 87)}...` : query;
424	      let text = theme.fg("toolTitle", theme.bold("WebSearch"));
425	      if (shown) text += ` ${theme.fg("accent", `"${shown}"`)}`;
426	      return new Text(text, 0, 0);
427	    },
428	    renderResult(result, { expanded }, theme) {
429	      if (!expanded) return new Container();
430	      const block = result.content.find((item) => item.type === "text");
431	      const text = block?.type === "text" ? block.text : "(no output)";
432	      return new Text(theme.fg("dim", text), 0, 0);
433	    },
434	  });
435	}
436	
437	export default function nativeToolOverridesExtension(pi: ExtensionAPI) {
438	  // CACHE CRITICAL: override Pi core's default load actions before this profile
439	  // registers Luke's native alias schemas. This keeps the system prompt/tools prefix
440	  // stable and prevents duplicate capability schemas (`agent`/`Agent`/`Task`,
441	  // `bash_output`/`BashOutput`, etc.) from being billed every turn.
442	  pi.hooks.removeAction(LOAD_HOOK, "agents");
443	  pi.hooks.removeAction(LOAD_HOOK, "bashBgJobs");
444	
445	  const isEnabled = makeIsEnabled(loadSelection());
446	  registerCanonicalNativeTools(pi, isEnabled);
447	  registerWebFetch(pi, isEnabled);
448	  registerWebSearch(pi, isEnabled);
449	}
450	
451	export const nativeToolNames = NATIVE_TOOL_NAMES;
452

