/**
 * native-tool-overrides
 *
 * Registers Luke's native tools by wrapping Pi's lowercase tool factories and overriding
 * their behavior — Edit argument repair, Bash timeout-to-background, deferred loading,
 * and Claude-style UI labels ("Read"/"Bash"/...) via ToolDefinition.label while keeping
 * upstream lowercase wire names (read/edit/write/grep/find/ls/bash). Also owns the
 * web_fetch/web_search marker tools (claude-bridge native server tools that throw on
 * local execute). This is more than aliasing: it is the override layer that keeps
 * custom tool behavior out of pi-mono-fork core.
 *
 * Lifts these tool definitions out of pi-mono-fork core so the fork can stay closer
 * to upstream Pi. The hardcoded tool-name references in `agent-session.ts` and `sdk.ts`
 * (defaultActiveToolNames, CLAUDE_BRIDGE_NATIVE_TOOL_NAMES) resolve to these
 * extension-provided tools at session startup via the runtime tool registry.
 *
 * Naming: lowercase wire names match core factories (so the extension tool overwrites
 * the core builtin by registry key and the bridge presents CC-canonical casing); UI
 * display comes from `label`. High-traffic edit/shell/read tools are always loaded;
 * utility tools stay provider-native deferred so they are available without billing
 * their full schemas every turn. Agent stays capitalized (core filters an extension
 * tool named "agent" when the core "agent" builtin exists).
 */

import {
  AGENTS_ENGINE_SERVICE_ID,
  BASH_BG_JOBS_SERVICE_ID,
  type AgentEngine,
  type BashBgJobStore,
  createBashBgJobStore,
  createBashToolDefinition,
  createEditToolDefinition,
  createFindToolDefinition,
  createGrepToolDefinition,
  createLsToolDefinition,
  createReadToolDefinition,
  createTaskListToolDefinition,
  createTaskOutputToolDefinition,
  createTaskStopToolDefinition,
  createUppercaseAgentToolDefinition,
  createWriteToolDefinition,
  type ExtensionAPI,
  onBashTimeout,
} from "@valkyriweb/pi-coding-agent";
import { Container, Text } from "@valkyriweb/pi-tui";
import { type Static, Type } from "typebox";
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";

// --- Per-profile tool selection (include / exclude) ----------------------------
//
// Lets a profile register only a subset of the canonical native tools without
// forking this extension. Resolution order (first wins per field):
//   1. env: PI_NATIVE_TOOL_INCLUDE / PI_NATIVE_TOOL_EXCLUDE (comma-separated)
//   2. settings.json: extensions.native-tool-overrides.{include,exclude}
//   3. defaults (register everything)
//
// `include` is an allowlist (only these register). `exclude` is a denylist
// (everything except these). If both resolve, include is applied first, then
// exclude removes from it. Names match the capability case-insensitively
// (e.g. "Agent", "agent" both exclude the Agent alias).
//
// CACHE CRITICAL: this is read once at load and gates which schemas enter the
// stable first-turn tools[] set. It must be deterministic per process; never
// derive it from per-turn state.
interface NativeToolSelection {
  include: Set<string> | null;
  exclude: Set<string>;
}

function parseNameList(raw: unknown): string[] {
  if (typeof raw === "string") return raw.split(",").map((s) => s.trim()).filter(Boolean);
  if (Array.isArray(raw)) return raw.filter((s): s is string => typeof s === "string").map((s) => s.trim()).filter(Boolean);
  return [];
}

function loadSelection(): NativeToolSelection {
  let includeNames = parseNameList(process.env.PI_NATIVE_TOOL_INCLUDE);
  let excludeNames = parseNameList(process.env.PI_NATIVE_TOOL_EXCLUDE);

  if (includeNames.length === 0 || excludeNames.length === 0) {
    const path = join(process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
    try {
      const raw = readFileSync(path, "utf8");
      const parsed = JSON.parse(raw) as {
        extensions?: { "native-tool-overrides"?: { include?: unknown; exclude?: unknown } };
      };
      const cfg = parsed.extensions?.["native-tool-overrides"];
      if (includeNames.length === 0) includeNames = parseNameList(cfg?.include);
      if (excludeNames.length === 0) excludeNames = parseNameList(cfg?.exclude);
    } catch {
      // No settings.json / unreadable — fall back to env + defaults.
    }
  }

  const norm = (s: string) => s.toLowerCase();
  return {
    include: includeNames.length > 0 ? new Set(includeNames.map(norm)) : null,
    exclude: new Set(excludeNames.map(norm)),
  };
}

function makeIsEnabled(selection: NativeToolSelection): (name: string) => boolean {
  return (name: string) => {
    const key = name.toLowerCase();
    if (selection.include && !selection.include.has(key)) return false;
    if (selection.exclude.has(key)) return false;
    return true;
  };
}

// --- Edit-tool argument repair (fork-local, kept out of pi core) ----------------
//
// Some models cram extra replacements onto one Edit call as numbered siblings
// (oldText2/newText2, oldText3/newText3, ...) instead of using the edits[] array.
// The core Edit schema is additionalProperties:false, so those calls hard-reject.
// Upstream already folds a single top-level oldText/newText pair; we extend that
// to numbered siblings here rather than patching core, so pi-mono-fork stays at
// upstream shape. We normalize the numbered pairs into edits[], then delegate to
// the upstream prepareArguments for its JSON-string + single-pair handling.
type EditReplacement = { oldText: string; newText: string };

function foldNumberedEditPairs(input: unknown): unknown {
  if (!input || typeof input !== "object") return input;
  const args = input as Record<string, unknown>;
  const pairs: EditReplacement[] = [];
  const consumed = new Set<string>();
  if (typeof args.oldText === "string" && typeof args.newText === "string") {
    pairs.push({ oldText: args.oldText, newText: args.newText });
    consumed.add("oldText").add("newText");
  }
  for (let n = 2; ; n++) {
    const oldKey = `oldText${n}`;
    const newKey = `newText${n}`;
    if (typeof args[oldKey] !== "string" || typeof args[newKey] !== "string") break;
    pairs.push({ oldText: args[oldKey] as string, newText: args[newKey] as string });
    consumed.add(oldKey).add(newKey);
  }
  if (pairs.length === 0) return input;
  const existing = Array.isArray(args.edits) ? (args.edits as EditReplacement[]) : [];
  const rest = Object.fromEntries(Object.entries(args).filter(([key]) => !consumed.has(key)));
  return { ...rest, edits: [...existing, ...pairs] };
}

function withNumberedEditRepair<T extends { prepareArguments?: (input: unknown) => unknown }>(definition: T): T {
  const upstreamPrepare = definition.prepareArguments;
  return {
    ...definition,
    prepareArguments: (input: unknown) => {
      const folded = foldNumberedEditPairs(input);
      return upstreamPrepare ? upstreamPrepare(folded) : folded;
    },
  };
}

// --- Pi-native tools (upstream-aligned lowercase names, capitalized UI labels) ---
// Names match core's lowercase factories (read/edit/write/grep/find/ls/bash) so the
// extension tool overwrites the core builtin by registry key and the bridge presents
// CC-canonical casing on the wire. Display stays "Read"/"Bash"/... via ToolDefinition
// .label. Agent stays capitalized (core filters an extension tool named "agent" when
// the core "agent" builtin exists); TaskOutput/TaskStop/TaskList are CC-canonical names
// with no lowercase upstream form.

const LOAD_HOOK = "load";
const NATIVE_TOOL_NAMES = [
  "read",
  "bash",
  "TaskOutput",
  "TaskStop",
  "TaskList",
  "edit",
  "write",
  "Agent",
  "grep",
  "find",
  "ls",
] as const;

// Core's Bash tool blocks `cd <cwd> && ...` with a "Blocked redundant cd" error to
// steer toward native tools / `-C` flags. Luke wants those to just run instead of
// erroring. We strip a leading redundant `cd <cwd>` (one that resolves to the session
// cwd) before core's guard sees the command, so it executes in cwd as intended. A cd
// to a *different* directory is left untouched (core already allows that). Done in the
// extension wrapper's prepareArguments so pi-mono-fork core stays at upstream shape.
const REDUNDANT_CD_PREFIX = /^(\s*cd\s+("[^"]+"|'[^']+'|(?:\\\S|\S)+)\s*(?:&&|;)\s*)(?=\S)/s;
function unquoteShellPath(value: string): string {
  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
    return value.slice(1, -1);
  }
  return value.replace(/\\ /g, " ");
}
export function stripRedundantCd(command: string, cwd: string): string {
  const match = REDUNDANT_CD_PREFIX.exec(command);
  if (!match) return command;
  let target = unquoteShellPath(match[2]!);
  if (target === "~" || target.startsWith("~/")) target = join(homedir(), target.slice(2));
  if (resolve(cwd, target) !== resolve(cwd)) return command;
  return command.slice(match[1]!.length);
}

function registerCanonicalNativeTools(pi: ExtensionAPI, isEnabled: (name: string) => boolean) {
  const cwd = process.cwd();
  const jobs = createBashBgJobStore();
  const agentOptions = { getEngine: () => pi.harness.use<AgentEngine>(AGENTS_ENGINE_SERVICE_ID) };

  pi.harness.provide<BashBgJobStore>(BASH_BG_JOBS_SERVICE_ID, jobs, { scope: "process", replace: true });

  // Register helper: skip tools the active profile selection excludes.
  const add = (name: string, definition: object) => {
    if (!isEnabled(name)) return;
    pi.registerTool(definition as Parameters<typeof pi.registerTool>[0]);
  };

  // CACHE CRITICAL: this extension owns the stable first-turn native tool
  // schema set for Luke's Pi profile. Keep this list deterministic and one
  // schema per capability. Dynamic tool decisions belong in tool-search, not
  // in this startup alias layer.
  add("read", {
    ...createReadToolDefinition(cwd, { label: "Read" }),
    alwaysLoad: true,
    replacesBuiltins: ["read"],
  });
  // Rewrite the bash_output/bash_kill mentions in core's Bash description to the
  // unified task_id tools this profile actually ships (TaskOutput/TaskStop).
  const bashDef = createBashToolDefinition(cwd, { label: "Bash" });
  add("bash", {
    ...bashDef,
    description: bashDef.description
      ?.replace(/bash_output\(bgId\)/g, "TaskOutput(task_id)")
      .replace(/bash_kill\(bgId\)/g, "TaskStop(task_id)"),
    // Strip a redundant leading `cd <cwd> &&` so it runs instead of hitting core's
    // "Blocked redundant cd" guard. Delegates to any upstream prepareArguments first.
    prepareArguments: (input: unknown) => {
      const args = (bashDef.prepareArguments ? bashDef.prepareArguments(input) : input) as
        | { command?: unknown }
        | undefined;
      if (args && typeof args.command === "string") {
        return { ...args, command: stripRedundantCd(args.command, cwd) };
      }
      return args;
    },
    alwaysLoad: true,
    // Core ships BOTH lowercase `bash` and capitalized `Bash` builtins; replace both
    // so this single lowercase `bash` is the only bash schema (no duplicate).
    replacesBuiltins: ["bash", "Bash"],
  });
  // Detach-on-timeout is Luke's opinion, not core's. The fork keeps a neutral
  // default (kill + report timeout); here we opt the Bash tool into Claude
  // Code-style auto-background: a timed-out command keeps running as a bg job,
  // readable via TaskOutput and stoppable via TaskStop. `t.background()` adopts
  // the live process into the same bg registry these tools already read.
  //
  // Install once as a process-wide preference and NEVER restore it on session
  // dispose. `onBashTimeout` mutates a single package-global resolver, and its
  // restore fns are not a real stack — restoring on every top-level dispose
  // (/new, /fork, switchSession) reverted the global to the core kill policy,
  // so a timed-out command was KILLED instead of detached until the next session
  // re-activated this extension (and stacked disposes clobbered it to kill
  // outright). The policy is idempotent — always the same detach closure — so
  // re-installing on each activation and never restoring keeps auto-background
  // reliably on. Regression: autobg-lifecycle.test.mjs.
  if (isEnabled("bash")) {
    onBashTimeout((t) => ({ backgroundedJobId: t.background().id }));
  }
  // CACHE CRITICAL: these utility aliases must remain provider-visible but
  // schema-deferred. Marking them alwaysLoad reintroduces the prompt-cache burst
  // where background/listing schemas are billed every turn. They are discovered
  // through the stable <deferred-tools> index and loaded through Anthropic
  // `defer_loading` / `tool_reference`, matching Claude Code and Codex.
  // Unified background-task tools (Claude Code task_id parity) over the core
  // task-registry seam: one id space across background bash jobs AND background
  // agent runs. These replace the bash-only BashOutput/KillShell. The bash log
  // rendering (tail/head/all, status header) is preserved inside TaskOutput.
  add("TaskOutput", {
    ...createTaskOutputToolDefinition(),
    deferLoading: true,
    replacesBuiltins: ["bash_output"],
  });
  add("TaskStop", {
    ...createTaskStopToolDefinition(),
    deferLoading: true,
    replacesBuiltins: ["bash_kill"],
  });
  add("TaskList", {
    ...createTaskListToolDefinition(),
    deferLoading: true,
  });
  add("edit", {
    ...withNumberedEditRepair(createEditToolDefinition(cwd, { label: "Edit" })),
    alwaysLoad: true,
    replacesBuiltins: ["edit"],
  });
  add("write", {
    ...createWriteToolDefinition(cwd, { label: "Write" }),
    alwaysLoad: true,
    replacesBuiltins: ["write"],
  });
  add("Agent", {
    ...createUppercaseAgentToolDefinition("", agentOptions),
    alwaysLoad: true,
  });
  add("grep", {
    ...createGrepToolDefinition(cwd, { label: "Grep" }),
    alwaysLoad: true,
    replacesBuiltins: ["grep"],
  });
  add("find", {
    ...createFindToolDefinition(cwd, { label: "Find" }),
    deferLoading: true,
    replacesBuiltins: ["find"],
  });
  add("ls", {
    ...createLsToolDefinition(cwd, { label: "Ls" }),
    deferLoading: true,
    replacesBuiltins: ["ls"],
  });

  pi.onSessionDispose(() => {
    jobs.killAll();
  });
}

// --- WebFetch / WebSearch marker tools -----------------------------------------
//
// These are native Anthropic/Claude server tools. The provider intercepts the
// tool call before local execute(); local execute() never legitimately runs.

const webFetchSchema = Type.Object({
  allowed_domains: Type.Optional(Type.Array(Type.String({ description: "Only allow fetching from these domains" }))),
  blocked_domains: Type.Optional(Type.Array(Type.String({ description: "Never fetch from these domains" }))),
  max_content_tokens: Type.Optional(
    Type.Number({ description: "Approximate maximum tokens used for fetched web page text content" }),
  ),
  use_cache: Type.Optional(
    Type.Boolean({
      description:
        "Whether to use cached content. Set false only when the user explicitly requests fresh content or rapidly-changing sources.",
    }),
  ),
});

type WebFetchInput = Static<typeof webFetchSchema>;

const webSearchSchema = Type.Object({
  query: Type.String({ description: "Search query" }),
  allowed_domains: Type.Optional(Type.Array(Type.String({ description: "Only allow results from these domains" }))),
  blocked_domains: Type.Optional(Type.Array(Type.String({ description: "Never return results from these domains" }))),
});

type WebSearchInput = Static<typeof webSearchSchema>;

const WEBFETCH_UNSUPPORTED = "WebFetch is only available with the claude-bridge provider";
const WEBFETCH_LOCAL = "WebFetch is a native Anthropic/Claude provider tool and should not execute locally";
const WEBSEARCH_UNSUPPORTED = "WebSearch is only available with the claude-bridge provider";
const WEBSEARCH_LOCAL = "WebSearch is a native Anthropic/Claude provider tool and should not execute locally";

function normalizeWebFetchInput(args: unknown): WebFetchInput {
  return args && typeof args === "object" ? (args as WebFetchInput) : {};
}

function normalizeWebSearchInput(args: unknown): WebSearchInput {
  const input = args && typeof args === "object" ? (args as WebSearchInput) : ({ query: "" } as WebSearchInput);
  if (input.allowed_domains?.length && input.blocked_domains?.length) {
    throw new Error("WebSearch accepts either allowed_domains or blocked_domains, not both");
  }
  return input;
}

function registerWebFetch(pi: ExtensionAPI, isEnabled: (name: string) => boolean) {
  // LLM/wire name is the Anthropic-native `web_fetch`; TUI displays "WebFetch" via label.
  if (!isEnabled("web_fetch")) return;
  pi.registerTool({
    name: "web_fetch",
    deferLoading: true,
    label: "WebFetch",
    description:
      "Fetch web page content using Anthropic/Claude's native web_fetch server tool. Only available for claude-bridge models.",
    promptSnippet: "Fetch web page content using Anthropic/Claude's native web_fetch server tool.",
    providers: ["claude-bridge"],
    parameters: webFetchSchema,
    prepareArguments: normalizeWebFetchInput,
    async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
      if (ctx.model?.provider !== "claude-bridge") throw new Error(WEBFETCH_UNSUPPORTED);
      throw new Error(WEBFETCH_LOCAL);
    },
    renderCall(args, theme) {
      const opts: string[] = [];
      if (args?.allowed_domains?.length) opts.push(`allow ${args.allowed_domains.join(", ")}`);
      if (args?.blocked_domains?.length) opts.push(`block ${args.blocked_domains.join(", ")}`);
      if (args?.use_cache === false) opts.push("fresh");
      const suffix = opts.length ? ` ${theme.fg("toolOutput", `(${opts.join("; ")})`)}` : "";
      return new Text(`${theme.fg("toolTitle", theme.bold("WebFetch"))}${suffix}`, 0, 0);
    },
    renderResult(result, { expanded }, theme) {
      if (!expanded) return new Container();
      const block = result.content.find((item) => item.type === "text");
      const text = block?.type === "text" ? block.text : "(no output)";
      return new Text(theme.fg("dim", text), 0, 0);
    },
  });
}

function registerWebSearch(pi: ExtensionAPI, isEnabled: (name: string) => boolean) {
  // LLM/wire name is the Anthropic-native `web_search`; TUI displays "WebSearch" via label.
  if (!isEnabled("web_search")) return;
  pi.registerTool({
    name: "web_search",
    deferLoading: true,
    label: "WebSearch",
    description:
      "Search the web using Anthropic/Claude's native web_search server tool. Only available for claude-bridge models.",
    promptSnippet: "Search the web using Anthropic/Claude's native web_search server tool.",
    providers: ["claude-bridge"],
    parameters: webSearchSchema,
    prepareArguments: normalizeWebSearchInput,
    async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
      if (ctx.model?.provider !== "claude-bridge") throw new Error(WEBSEARCH_UNSUPPORTED);
      throw new Error(WEBSEARCH_LOCAL);
    },
    renderCall(args, theme) {
      const query = typeof args?.query === "string" ? args.query : "";
      const shown = query.length > 90 ? `${query.slice(0, 87)}...` : query;
      let text = theme.fg("toolTitle", theme.bold("WebSearch"));
      if (shown) text += ` ${theme.fg("accent", `"${shown}"`)}`;
      return new Text(text, 0, 0);
    },
    renderResult(result, { expanded }, theme) {
      if (!expanded) return new Container();
      const block = result.content.find((item) => item.type === "text");
      const text = block?.type === "text" ? block.text : "(no output)";
      return new Text(theme.fg("dim", text), 0, 0);
    },
  });
}

export default function nativeToolOverridesExtension(pi: ExtensionAPI) {
  // CACHE CRITICAL: override Pi core's default load actions before this profile
  // registers Luke's native alias schemas. This keeps the system prompt/tools prefix
  // stable and prevents duplicate capability schemas (`agent`/`Agent`/`Task`,
  // `bash_output`/`BashOutput`, etc.) from being billed every turn.
  pi.hooks.removeAction(LOAD_HOOK, "agents");
  pi.hooks.removeAction(LOAD_HOOK, "bashBgJobs");

  const isEnabled = makeIsEnabled(loadSelection());
  registerCanonicalNativeTools(pi, isEnabled);
  registerWebFetch(pi, isEnabled);
  registerWebSearch(pi, isEnabled);
}

export const nativeToolNames = NATIVE_TOOL_NAMES;

