61	type GoalWaitProvider = {
62		kind: string;
63		isPending(wait: GoalWaitCondition): boolean;
64		getResumePayload?(wait: GoalWaitCondition): unknown;
65	};
66	
67	type GoalWaitHost = {
68		setWaitingOn(wait: GoalWaitCondition, ctx?: ExtensionContext): boolean;
69	};
70	
71	type GoalWaitRegistry = {
72		providers: Map<string, GoalWaitProvider>;
73		hosts: Map<string, GoalWaitHost>;
74		registerProvider(provider: GoalWaitProvider): () => void;
75		registerHost(id: string, host: GoalWaitHost): () => void;
76		requestWait(wait: GoalWaitCondition, ctx?: ExtensionContext): boolean;
77	};
78	
79	interface MonitorState {
80		id: string;
81		description: string;
82		command: string;
83		cwd: string;
84		status: MonitorStatus;
85		startedAt: number;
86		endedAt?: number;
87		exitCode?: number | null;
88		signal?: string | null;
89		proc: ChildProcess | null;
90		recentLines: string[]; // ring buffer
91		totalLines: number;
92		pendingLines: string[]; // batched for notify
93		logPath: string;
94		suppressedDuplicateLines: number;
95		triggerOnOutput: boolean;
96		triggerOnExit: boolean;
97		flushTimer?: NodeJS.Timeout;
98		timeoutTimer?: NodeJS.Timeout;
99		wakeCount: number;
100		maxWakeups: number;
101		maxRuntimeMs?: number;
102		outputBytes: number;
103		outputWakeDisabledReason?: string;
104	}
105	
106	const monitors = new Map<string, MonitorState>();
107	let counter = 0;
108	let activeCtx: ExtensionContext | undefined;
109	// True between session_shutdown and the next session_start, OR when a stale-ctx
110	// throw is observed from pi.sendMessage / ctx.ui.* . While stale, all action
111	// methods on the captured `pi`/`ctx` are forbidden — calling them throws and
112	// the throw is unhandled inside ChildProcess emit() callbacks, which crashes
113	// the whole agent. We detect this and silently drop notifications instead.
114	//
115	// Why this is needed: dispose() (used for fork / newSession / switchSession /
116	// child-agent end) invalidates the runtime WITHOUT firing session_shutdown, so
117	// detached monitor procs (proc.unref + detached:true) survive past invalidation
118	// and their async exit/error callbacks would otherwise hit the dead runtime.
119	let runtimeStale = false;
120	
121	const GOAL_WAIT_REGISTRY_SYMBOL = Symbol.for("valkyriweb.piGoal.waitRegistry.v1");
122	
123	function getGoalWaitRegistry(): GoalWaitRegistry {
124		const target = globalThis as typeof globalThis & { [GOAL_WAIT_REGISTRY_SYMBOL]?: GoalWaitRegistry };
125		if (target[GOAL_WAIT_REGISTRY_SYMBOL]) return target[GOAL_WAIT_REGISTRY_SYMBOL];
126		const registry: GoalWaitRegistry = {
127			providers: new Map<string, GoalWaitProvider>(),
128			hosts: new Map<string, GoalWaitHost>(),
129			registerProvider(provider) {
130				registry.providers.set(provider.kind, provider);
131				return () => {
132					if (registry.providers.get(provider.kind) === provider) {
133						registry.providers.delete(provider.kind);
134					}
135				};
136			},
137			registerHost(id, host) {
138				registry.hosts.set(id, host);
139				return () => {
140					if (registry.hosts.get(id) === host) {
141						registry.hosts.delete(id);
142					}
143				};
144			},
145			requestWait(wait, ctx) {
146				let accepted = false;
147				for (const host of registry.hosts.values()) {
148					accepted = host.setWaitingOn(wait, ctx) || accepted;
149				}
150				return accepted;
151			},
152		};
153		target[GOAL_WAIT_REGISTRY_SYMBOL] = registry;
154		return registry;
155	}
156	
157	function isStaleCtxError(err: unknown): boolean {
158		const msg = err instanceof Error ? err.message : String(err);
159		return msg.includes("extension ctx is stale");
160	}
161	
162	function markStaleAndCleanup(): void {
163		if (runtimeStale) return;
164		runtimeStale = true;
165		// Best-effort: stop detached child processes so they don't linger forever.
166		// Don't touch ctx/pi here — they're dead.
167		for (const m of monitors.values()) {
168			if (m.status === "running") {
169				try {
170					killMonitor(m);
171				} catch {
172					/* swallow */
173				}
174			}
175		}
176	}
177	
178	function safeSend(
179		pi: ExtensionAPI,
180		message: Parameters<ExtensionAPI["sendMessage"]>[0],
181		options?: Parameters<ExtensionAPI["sendMessage"]>[1],
182	): void {
183		if (runtimeStale) return;
184		try {
185			pi.sendMessage(message, options);
186		} catch (err) {
187			if (isStaleCtxError(err)) {
188				markStaleAndCleanup();
189				return;
190			}
191			// Unknown failure — log to stderr but never throw out of an event handler.
192			try {
193				process.stderr.write(
194					`[monitor] sendMessage failed: ${err instanceof Error ? err.message : String(err)}\n`,
195				);
196			} catch {
197				/* noop */
198			}
199		}
200	}
201	
202	function safeFooter(ctx: ExtensionContext | undefined): void {
203		if (runtimeStale) return;
204		try {
205			updateFooter(ctx);
206		} catch (err) {
207			if (isStaleCtxError(err)) markStaleAndCleanup();
208		}
209	}
210	
211	function safeNotify(ctx: ExtensionContext | undefined, message: string, type: "info" | "warning" | "error" = "info"): void {
212		if (runtimeStale || !ctx?.hasUI) return;
213		try {
214			ctx.ui.notify(message, type);
215		} catch (err) {
216			if (isStaleCtxError(err)) markStaleAndCleanup();
217		}
218	}
219	
220	const RING_SIZE = 200;
221	const BATCH_INTERVAL_MS = 2_000;
222	const MAX_LINES_PER_BATCH = 100;
223	const NOTIFY_TAIL_LINES = 5;
224	const DEFAULT_MAX_OUTPUT_WAKEUPS = 20;
225	const MAX_OUTPUT_WAKEUPS = 100;
226	const DEFAULT_MAX_RUNTIME_SECONDS = 60 * 60;
227	const MAX_RUNTIME_SECONDS = 12 * 60 * 60;
228	const STATUS_DEFAULT_TAIL_LINES = 10;
229	const STATUS_MAX_TAIL_LINES = 40;
230	const READ_DEFAULT_MAX_LINES = 100;
231	const READ_MAX_LINES = 1_000;
232	const LOG_DIR = join(process.env.HOME ?? process.cwd(), ".pi", "agent", "monitor-logs");
233	
234	class MonitorProcessStartError {
235		readonly _tag = "MonitorProcessStartError";
236		readonly cause: unknown;
237	
238		constructor(cause: unknown) {
239			this.cause = cause;
240		}
241	}
242	
243	function startMonitorProcess(command: string, cwd: string): Effect.Effect<ChildProcess, MonitorProcessStartError> {
244		return Effect.try({
245			try: () =>
246				spawn(command, {
247					cwd,
248					shell: true,
249					stdio: ["ignore", "pipe", "pipe"],
250					// detached creates a new process group so we can kill grandchildren
251					detached: process.platform !== "win32",
252				}),
253			catch: (cause) => new MonitorProcessStartError(cause),
254		});
255	}
256	
257	function toError(cause: unknown): Error {
258		return cause instanceof Error ? cause : new Error(String(cause));
259	}
260	
261	function newId(): string {
262		counter++;
263		return `mon_${Date.now().toString(36)}_${counter}`;
264	}
265	
266	function ensureLogDir(): void {
267		try { mkdirSync(LOG_DIR, { recursive: true }); } catch { /* noop */ }
268	}
269	
270	function logPathFor(id: string): string {
271		ensureLogDir();
272		return join(LOG_DIR, `${id}.log`);
273	}
274	
275	function sanitizeLine(line: string): string {
276		return line
277			.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, "")
278			.replace(/\x1b\][^\x07]*(?:\x07|\x1b\\)/g, "")
279			.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, "")
280			.trimEnd();
281	}
282	
283	function clamp(n: number | undefined, fallback: number, max: number): number {
284		if (!Number.isFinite(n) || !n || n <= 0) return fallback;
285		return Math.min(Math.floor(n), max);
