type GoalWaitProvider = {
	kind: string;
	isPending(wait: GoalWaitCondition): boolean;
	getResumePayload?(wait: GoalWaitCondition): unknown;
};

type GoalWaitHost = {
	setWaitingOn(wait: GoalWaitCondition, ctx?: ExtensionContext): boolean;
};

type GoalWaitRegistry = {
	providers: Map<string, GoalWaitProvider>;
	hosts: Map<string, GoalWaitHost>;
	registerProvider(provider: GoalWaitProvider): () => void;
	registerHost(id: string, host: GoalWaitHost): () => void;
	requestWait(wait: GoalWaitCondition, ctx?: ExtensionContext): boolean;
};

interface MonitorState {
	id: string;
	description: string;
	command: string;
	cwd: string;
	status: MonitorStatus;
	startedAt: number;
	endedAt?: number;
	exitCode?: number | null;
	signal?: string | null;
	proc: ChildProcess | null;
	recentLines: string[]; // ring buffer
	totalLines: number;
	pendingLines: string[]; // batched for notify
	logPath: string;
	suppressedDuplicateLines: number;
	triggerOnOutput: boolean;
	triggerOnExit: boolean;
	flushTimer?: NodeJS.Timeout;
	timeoutTimer?: NodeJS.Timeout;
	wakeCount: number;
	maxWakeups: number;
	maxRuntimeMs?: number;
	outputBytes: number;
	outputWakeDisabledReason?: string;
}

const monitors = new Map<string, MonitorState>();
let counter = 0;
let activeCtx: ExtensionContext | undefined;
// True between session_shutdown and the next session_start, OR when a stale-ctx
// throw is observed from pi.sendMessage / ctx.ui.* . While stale, all action
// methods on the captured `pi`/`ctx` are forbidden — calling them throws and
// the throw is unhandled inside ChildProcess emit() callbacks, which crashes
// the whole agent. We detect this and silently drop notifications instead.
//
// Why this is needed: dispose() (used for fork / newSession / switchSession /
// child-agent end) invalidates the runtime WITHOUT firing session_shutdown, so
// detached monitor procs (proc.unref + detached:true) survive past invalidation
// and their async exit/error callbacks would otherwise hit the dead runtime.
let runtimeStale = false;

const GOAL_WAIT_REGISTRY_SYMBOL = Symbol.for("valkyriweb.piGoal.waitRegistry.v1");

function getGoalWaitRegistry(): GoalWaitRegistry {
	const target = globalThis as typeof globalThis & { [GOAL_WAIT_REGISTRY_SYMBOL]?: GoalWaitRegistry };
	if (target[GOAL_WAIT_REGISTRY_SYMBOL]) return target[GOAL_WAIT_REGISTRY_SYMBOL];
	const registry: GoalWaitRegistry = {
		providers: new Map<string, GoalWaitProvider>(),
		hosts: new Map<string, GoalWaitHost>(),
		registerProvider(provider) {
			registry.providers.set(provider.kind, provider);
			return () => {
				if (registry.providers.get(provider.kind) === provider) {
					registry.providers.delete(provider.kind);
				}
			};
		},
		registerHost(id, host) {
			registry.hosts.set(id, host);
			return () => {
				if (registry.hosts.get(id) === host) {
					registry.hosts.delete(id);
				}
			};
		},
		requestWait(wait, ctx) {
			let accepted = false;
			for (const host of registry.hosts.values()) {
				accepted = host.setWaitingOn(wait, ctx) || accepted;
			}
			return accepted;
		},
	};
	target[GOAL_WAIT_REGISTRY_SYMBOL] = registry;
	return registry;
}

function isStaleCtxError(err: unknown): boolean {
	const msg = err instanceof Error ? err.message : String(err);
	return msg.includes("extension ctx is stale");
}

function markStaleAndCleanup(): void {
	if (runtimeStale) return;
	runtimeStale = true;
	// Best-effort: stop detached child processes so they don't linger forever.
	// Don't touch ctx/pi here — they're dead.
	for (const m of monitors.values()) {
		if (m.status === "running") {
			try {
				killMonitor(m);
			} catch {
				/* swallow */
			}
		}
	}
}

function safeSend(
	pi: ExtensionAPI,
	message: Parameters<ExtensionAPI["sendMessage"]>[0],
	options?: Parameters<ExtensionAPI["sendMessage"]>[1],
): void {
	if (runtimeStale) return;
	try {
		pi.sendMessage(message, options);
	} catch (err) {
		if (isStaleCtxError(err)) {
			markStaleAndCleanup();
			return;
		}
		// Unknown failure — log to stderr but never throw out of an event handler.
		try {
			process.stderr.write(
				`[monitor] sendMessage failed: ${err instanceof Error ? err.message : String(err)}\n`,
			);
		} catch {
			/* noop */
		}
	}
}

function safeFooter(ctx: ExtensionContext | undefined): void {
	if (runtimeStale) return;
	try {
		updateFooter(ctx);
	} catch (err) {
		if (isStaleCtxError(err)) markStaleAndCleanup();
	}
}

function safeNotify(ctx: ExtensionContext | undefined, message: string, type: "info" | "warning" | "error" = "info"): void {
	if (runtimeStale || !ctx?.hasUI) return;
	try {
		ctx.ui.notify(message, type);
	} catch (err) {
		if (isStaleCtxError(err)) markStaleAndCleanup();
	}
}

const RING_SIZE = 200;
const BATCH_INTERVAL_MS = 2_000;
const MAX_LINES_PER_BATCH = 100;
const NOTIFY_TAIL_LINES = 5;
const DEFAULT_MAX_OUTPUT_WAKEUPS = 20;
const MAX_OUTPUT_WAKEUPS = 100;
const DEFAULT_MAX_RUNTIME_SECONDS = 60 * 60;
const MAX_RUNTIME_SECONDS = 12 * 60 * 60;
const STATUS_DEFAULT_TAIL_LINES = 10;
const STATUS_MAX_TAIL_LINES = 40;
const READ_DEFAULT_MAX_LINES = 100;
const READ_MAX_LINES = 1_000;
const LOG_DIR = join(process.env.HOME ?? process.cwd(), ".pi", "agent", "monitor-logs");

class MonitorProcessStartError {
	readonly _tag = "MonitorProcessStartError";
	readonly cause: unknown;

	constructor(cause: unknown) {
		this.cause = cause;
	}
}

function startMonitorProcess(command: string, cwd: string): Effect.Effect<ChildProcess, MonitorProcessStartError> {
	return Effect.try({
		try: () =>
			spawn(command, {
				cwd,
				shell: true,
				stdio: ["ignore", "pipe", "pipe"],
				// detached creates a new process group so we can kill grandchildren
				detached: process.platform !== "win32",
			}),
		catch: (cause) => new MonitorProcessStartError(cause),
	});
}

function toError(cause: unknown): Error {
	return cause instanceof Error ? cause : new Error(String(cause));
}

function newId(): string {
	counter++;
	return `mon_${Date.now().toString(36)}_${counter}`;
}

function ensureLogDir(): void {
	try { mkdirSync(LOG_DIR, { recursive: true }); } catch { /* noop */ }
}

function logPathFor(id: string): string {
	ensureLogDir();
	return join(LOG_DIR, `${id}.log`);
}

function sanitizeLine(line: string): string {
	return line
		.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, "")
		.replace(/\x1b\][^\x07]*(?:\x07|\x1b\\)/g, "")
		.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, "")
		.trimEnd();
}

function clamp(n: number | undefined, fallback: number, max: number): number {
	if (!Number.isFinite(n) || !n || n <= 0) return fallback;
	return Math.min(Math.floor(n), max);
}

function activeCount(): number {
	let n = 0;
	for (const m of monitors.values()) if (m.status === "running") n++;
	return n;
}

function statusGlyph(s: MonitorStatus): string {
	switch (s) {
		case "running":
			return "●";
		case "exited":
			return "✓";
		case "killed":
			return "■";
		case "failed":
			return "✗";
	}
}

// -----------------------------------------------------------------------------
// Footer
// -----------------------------------------------------------------------------

function updateFooter(ctx: ExtensionContext | undefined): void {
	if (!ctx || !ctx.hasUI) return;
	const n = activeCount();
	const theme = ctx.ui.theme;
	if (n === 0) {
		ctx.ui.setStatus("monitor", undefined);
		return;
	}
	const dot = theme.fg("accent", "● ");
	const tail = theme.fg(
		"dim",
		`${n} monitor${n !== 1 ? "s" : ""} · ↓ or alt+m`,
	);
	ctx.ui.setStatus("monitor", dot + tail);
}

// -----------------------------------------------------------------------------
// Process lifecycle
// -----------------------------------------------------------------------------

function flushNotify(pi: ExtensionAPI, m: MonitorState): void {
	if (m.pendingLines.length === 0) return;
	const lines = m.pendingLines;
	m.pendingLines = [];
	if (m.flushTimer) {
		clearTimeout(m.flushTimer);
		m.flushTimer = undefined;
	}
	if (runtimeStale) return;
	const tail = lines.slice(-NOTIFY_TAIL_LINES);
	const suppressed = Math.max(0, lines.length - tail.length);
	const duplicateNote = m.suppressedDuplicateLines > 0 ? ` · ${m.suppressedDuplicateLines} duplicate line${m.suppressedDuplicateLines !== 1 ? "s" : ""} suppressed` : "";
	const body = tail.length > 0 ? `\n${tail.join("\n")}` : "";
	const suffix = suppressed > 0 ? `\n…(${suppressed} more lines saved to ${m.logPath})` : "";
	if (!m.triggerOnOutput) {
		// Claude/Codex-style backgrounding: output updates the UI/log, but does not
		// inject steering messages into the active agent loop. This prevents a log
		// tail or watcher from waking the model on every batch and causing the
		// "waited for background terminal" ping-pong Luke reported.
		safeNotify(activeCtx, `monitor ${m.description}: ${lines.length} new line${lines.length !== 1 ? "s" : ""} · ${m.logPath}`);
		return;
	}
	if (m.wakeCount >= m.maxWakeups) {
		m.triggerOnOutput = false;
		m.outputWakeDisabledReason = `maxWakeups ${m.maxWakeups} reached`;
		safeNotify(activeCtx, `monitor ${m.description}: output wakeups disabled after ${m.maxWakeups}; continuing to log to ${m.logPath}`, "warning");
		return;
	}
	m.wakeCount++;
	const wakeNote = `wake ${m.wakeCount}/${m.maxWakeups}`;
	safeSend(
		pi,
		{
			customType: "monitor-event",
			content: `[monitor ${m.description}] ${lines.length} new line${lines.length !== 1 ? "s" : ""} · ${wakeNote}${duplicateNote} · full log: ${m.logPath}${body}${suffix}`,
			display: true,
			details: { monitorId: m.id, tail, status: m.status, logPath: m.logPath, suppressed, totalLines: m.totalLines, wakeCount: m.wakeCount, maxWakeups: m.maxWakeups },
		},
		{ deliverAs: "steer", triggerTurn: true },
	);
}

function scheduleFlush(pi: ExtensionAPI, m: MonitorState): void {
	if (m.pendingLines.length >= MAX_LINES_PER_BATCH) {
		flushNotify(pi, m);
		return;
	}
	if (m.flushTimer) return;
	m.flushTimer = setTimeout(() => flushNotify(pi, m), BATCH_INTERVAL_MS);
}

function ingest(pi: ExtensionAPI, m: MonitorState, chunk: Buffer | string): void {
	const text = typeof chunk === "string" ? chunk : chunk.toString("utf8");
	m.outputBytes += Buffer.byteLength(text, "utf8");
	for (const raw of text.split(/\r?\n/)) {
		if (!raw) continue;
		const line = sanitizeLine(raw);
		try {
			appendFileSync(m.logPath, `${line}\n`, "utf8");
		} catch {
			/* keep monitoring even if log persistence fails */
		}
		m.totalLines++;
		m.recentLines.push(line);
		if (m.recentLines.length > RING_SIZE) m.recentLines.shift();
		m.pendingLines.push(line);
	}
	scheduleFlush(pi, m);
}

function killMonitor(m: MonitorState): void {
	if (m.proc && m.status === "running") {
		// Mark killed immediately so the exit guard can suppress notifications
		m.status = "killed";
		m.endedAt = Date.now();

		// Cancel pending flush timer and clear any buffered lines immediately
		if (m.flushTimer) {
			clearTimeout(m.flushTimer);
			m.flushTimer = undefined;
		}
		m.pendingLines = [];
		if (m.timeoutTimer) {
			clearTimeout(m.timeoutTimer);
			m.timeoutTimer = undefined;
		}

		const proc = m.proc;
		const pid = proc.pid;

		if (process.platform !== "win32" && pid != null) {
			// Kill the entire process group (negative PID) so grandchildren die too
			try {
				process.kill(-pid, "SIGTERM");
			} catch {
				// Process may already be gone; fall back to direct signal
				try { proc.kill("SIGTERM"); } catch { /* noop */ }
			}
			setTimeout(() => {
				try {
					process.kill(-pid, "SIGKILL");
				} catch {
					try { proc.kill("SIGKILL"); } catch { /* noop */ }
				}
			}, 3000);
		} else if (pid != null) {
			// Windows: taskkill /F /T kills the process tree
			try {
				execSync(`taskkill /F /T /PID ${pid}`, { stdio: "ignore" });
			} catch {
				try { proc.kill("SIGTERM"); } catch { /* noop */ }
				setTimeout(() => { try { proc.kill("SIGKILL"); } catch { /* noop */ } }, 3000);
			}
		}
	}
}

function cancelLatest(pi: ExtensionAPI, ctx: ExtensionContext): boolean {
	const running = [...monitors.values()].filter((m) => m.status === "running");
	if (running.length === 0) return false;
	const m = running[running.length - 1]!;
	killMonitor(m);
	ctx.ui.notify(`Stopped monitor: ${m.description}`, "info");
	return true;
}

