461	async function openDialog(pi: ExtensionAPI, ctx: ExtensionContext): Promise<void> {
462		if (!ctx.hasUI) {
463			ctx.ui.notify("Monitors require interactive mode", "error");
464			return;
465		}
466		const all = [...monitors.values()].sort((a, b) => {
467			const ar = a.status === "running" ? 0 : 1;
468			const br = b.status === "running" ? 0 : 1;
469			if (ar !== br) return ar - br;
470			return b.startedAt - a.startedAt;
471		});
472		if (all.length === 0) {
473			ctx.ui.notify("No monitors", "info");
474			return;
475		}
476	
477		const items: SelectItem[] = all.map((m) => ({
478			value: m.id,
479			label: `${statusGlyph(m.status)} ${m.description}`,
480			description: `${m.status} · ${m.totalLines} line${m.totalLines !== 1 ? "s" : ""} · ${m.command.slice(0, 80)}`,
481		}));
482	
483		type Action = { type: "view" | "kill"; id: string } | null;
484		const action = await ctx.ui.custom<Action>((tui, theme, _kb, done) => {
485			const container = new Container();
486			container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
487			container.addChild(
488				new Text(theme.fg("accent", theme.bold("Monitors")), 1, 0),
489			);
490	
491			const list = new SelectList(items, Math.min(items.length, 12), {
492				selectedPrefix: (t) => theme.fg("accent", t),
493				selectedText: (t) => theme.fg("accent", t),
494				description: (t) => theme.fg("muted", t),
495				scrollInfo: (t) => theme.fg("dim", t),
496				noMatch: (t) => theme.fg("warning", t),
497			});
498			let focusedId: string = items[0]!.value as string;
499			// SelectList from pi-tui exposes onFocus in current builds; if missing,
500			// we fall back to killing the first item.
501			(list as unknown as { onFocus?: (id: string) => void }).onFocus = (id: string) => {
502				focusedId = id;
503			};
504			list.onSelect = (item) => done({ type: "view", id: item.value as string });
505			list.onCancel = () => done(null);
506			container.addChild(list);
507	
508			container.addChild(
509				new Text(
510					theme.fg("dim", "↑↓ select · enter view · x kill · esc close"),
511					1,
512					0,
513				),
514			);
515			container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
516	
517			return {
518				render: (w) => container.render(w),
519				invalidate: () => container.invalidate(),
520				handleInput: (data: string) => {
521					if (data === "x" || data === "X") {
522						done({ type: "kill", id: focusedId });
523						return;
524					}
525					list.handleInput(data);
526					tui.requestRender();
527				},
528			};
529		});
530	
531		if (!action) return;
532		const m = monitors.get(action.id);
533		if (!m) return;
534		if (action.type === "kill") {
535			killMonitor(m);
536			ctx.ui.notify(`Stopped: ${m.description}`, "info");
537			updateFooter(ctx);
538			return;
539		}
540		await viewMonitor(ctx, m);
541	}
