async function openDialog(pi: ExtensionAPI, ctx: ExtensionContext): Promise<void> {
	if (!ctx.hasUI) {
		ctx.ui.notify("Monitors require interactive mode", "error");
		return;
	}
	const all = [...monitors.values()].sort((a, b) => {
		const ar = a.status === "running" ? 0 : 1;
		const br = b.status === "running" ? 0 : 1;
		if (ar !== br) return ar - br;
		return b.startedAt - a.startedAt;
	});
	if (all.length === 0) {
		ctx.ui.notify("No monitors", "info");
		return;
	}

	const items: SelectItem[] = all.map((m) => ({
		value: m.id,
		label: `${statusGlyph(m.status)} ${m.description}`,
		description: `${m.status} · ${m.totalLines} line${m.totalLines !== 1 ? "s" : ""} · ${m.command.slice(0, 80)}`,
	}));

	type Action = { type: "view" | "kill"; id: string } | null;
	const action = await ctx.ui.custom<Action>((tui, theme, _kb, done) => {
		const container = new Container();
		container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
		container.addChild(
			new Text(theme.fg("accent", theme.bold("Monitors")), 1, 0),
		);

		const list = new SelectList(items, Math.min(items.length, 12), {
			selectedPrefix: (t) => theme.fg("accent", t),
			selectedText: (t) => theme.fg("accent", t),
			description: (t) => theme.fg("muted", t),
			scrollInfo: (t) => theme.fg("dim", t),
			noMatch: (t) => theme.fg("warning", t),
		});
		let focusedId: string = items[0]!.value as string;
		// SelectList from pi-tui exposes onFocus in current builds; if missing,
		// we fall back to killing the first item.
		(list as unknown as { onFocus?: (id: string) => void }).onFocus = (id: string) => {
			focusedId = id;
		};
		list.onSelect = (item) => done({ type: "view", id: item.value as string });
		list.onCancel = () => done(null);
		container.addChild(list);

		container.addChild(
			new Text(
				theme.fg("dim", "↑↓ select · enter view · x kill · esc close"),
				1,
				0,
			),
		);
		container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));

		return {
			render: (w) => container.render(w),
			invalidate: () => container.invalidate(),
			handleInput: (data: string) => {
				if (data === "x" || data === "X") {
					done({ type: "kill", id: focusedId });
					return;
				}
				list.handleInput(data);
				tui.requestRender();
			},
		};
	});

	if (!action) return;
	const m = monitors.get(action.id);
	if (!m) return;
	if (action.type === "kill") {
		killMonitor(m);
		ctx.ui.notify(`Stopped: ${m.description}`, "info");
		updateFooter(ctx);
		return;
	}
	await viewMonitor(ctx, m);
}

async function viewMonitor(ctx: ExtensionContext, m: MonitorState): Promise<void> {
	await ctx.ui.custom<null>((_tui, theme, _kb, done) => {
		const container = new Container();
		container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
		container.addChild(
			new Text(theme.fg("accent", theme.bold(`Monitor: ${m.description}`)), 1, 0),
		);
		const exitInfo =
			m.status === "running"
				? ""
				: ` · exit ${m.exitCode ?? "—"}${m.signal ? ` (${m.signal})` : ""}`;
		container.addChild(
			new Text(
				theme.fg(
					"muted",
					`id ${m.id} · ${m.status}${exitInfo} · ${m.totalLines} lines`,
				),
				1,
				0,
			),
		);
		container.addChild(new Text(theme.fg("dim", `$ ${m.command}`), 1, 0));
		container.addChild(new Text("", 1, 0));

		const tail = m.recentLines.slice(-25);
		if (tail.length === 0) {
			container.addChild(new Text(theme.fg("dim", "(no output yet)"), 1, 0));
		} else {
			for (const line of tail) container.addChild(new Text(line, 1, 0));
		}

		container.addChild(new Text("", 1, 0));
		container.addChild(
			new Text(
				theme.fg(
					"dim",
					m.status === "running"
						? "x kill · esc/enter close"
						: "esc/enter close",
				),
				1,
				0,
			),
		);
		container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));

		return {
			render: (w) => container.render(w),
			invalidate: () => container.invalidate(),
			handleInput: (data: string) => {
				if (matchesKey(data, "escape") || matchesKey(data, "return")) {
					done(null);
					return;
				}
				if ((data === "x" || data === "X") && m.status === "running") {
					killMonitor(m);
					ctx.ui.notify(`Stopped: ${m.description}`, "info");
					updateFooter(ctx);
					done(null);
				}
			},
		};
	});
}

