function installEditorWrapper(pi: ExtensionAPI, ctx: ExtensionContext): void {
	const previous = ctx.ui.getEditorComponent();

	// Shared intercept logic — runs regardless of which editor owns the base.
	function interceptInput(data: string, delegate: (d: string) => void): void {
		const empty = !ctx.ui.getEditorText().trim();
		if (empty) {
			// Down arrow: open the monitors dialog (only when monitors exist).
			if (matchesKey(data, "down") && monitors.size > 0) {
				openDialog(pi, ctx).catch(() => {});
				return;
			}
			// Esc: stop the most recent running monitor instead of aborting agent.
			if (matchesKey(data, "escape") && activeCount() > 0) {
				if (cancelLatest(pi, ctx)) {
					updateFooter(ctx);
					return;
				}
			}
		}
		delegate(data);
	}

	class MonitorEditor extends CustomEditor {
		handleInput(data: string): void {
			interceptInput(data, (d) => super.handleInput(d));
		}
	}

	ctx.ui.setEditorComponent((tui, theme, kb) => {
		if (previous) {
			// Another extension already owns the editor — wrap its handleInput
			// rather than bypassing our intercepts entirely.
			const inner = previous(tui, theme, kb);
			const orig = inner.handleInput.bind(inner);
			inner.handleInput = (data: string) => interceptInput(data, orig);
			return inner;
		}
		return new MonitorEditor(tui, theme, kb);
	});
}

