import assert from "node:assert/strict";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const mod = await jiti.import("./index.ts");
const factory = mod.default ?? mod;

const tools = [];
const removedActions = [];
const services = new Map();
let disposeHandler;
const stubApi = {
  on: () => {},
  registerTool: (tool) => tools.push(tool),
  registerCommand: () => {},
  registerShortcut: () => {},
  registerFlag: () => {},
  onSessionDispose: (handler) => {
    disposeHandler = handler;
  },
  hooks: {
    removeAction: (hook, id) => removedActions.push([hook, id]),
  },
  harness: {
    provide: (id, service) => {
      services.set(id, service);
      return { id, current: () => service, replace: (next) => services.set(id, next), dispose: () => services.delete(id) };
    },
    use: (id) => services.get(id),
  },
};

factory(stubApi);

const names = tools.map((tool) => tool.name);
// Upstream-aligned lowercase wire names; Agent + Task* keep CC-canonical casing.
const expected = [
  "read", "bash", "TaskOutput", "TaskStop", "TaskList", "edit", "write", "Agent", "grep", "find", "ls",
  "web_fetch",
  "web_search",
];
assert.deepEqual(names, expected, `native-tool-overrides tool set: got ${JSON.stringify(names)}`);
assert.deepEqual(
  removedActions,
  [["load", "agents"], ["load", "bashBgJobs"]],
  "native-tool-overrides replaces Pi core native load actions",
);
assert.equal(names.includes("Task"), false, "Task legacy alias is not registered");
// Capitalized name variants (the old aliases) and the lowercase agent twin must NOT register.
for (const name of ["Read", "Edit", "Write", "Grep", "Find", "Ls", "WebFetch", "WebSearch", "bash_output", "bash_kill", "agent"]) {
  assert.equal(names.includes(name), false, `${name} duplicate/legacy alias is not registered`);
}
// Wire name is lowercase (upstream); UI label stays Claude-style capitalized.
const expectedLabels = {
  read: "Read", bash: "Bash", edit: "Edit", write: "Write", grep: "Grep", find: "Find", ls: "Ls",
  Agent: "Agent", TaskOutput: "TaskOutput", TaskStop: "TaskStop", TaskList: "TaskList",
  web_fetch: "WebFetch", web_search: "WebSearch",
};
for (const tool of tools) {
  assert.equal(typeof tool.execute, "function", `${tool.name} has execute()`);
  assert.equal(typeof tool.parameters, "object", `${tool.name} has parameters`);
  assert.equal(tool.label, expectedLabels[tool.name], `${tool.name} label is ${expectedLabels[tool.name]}`);
}
for (const name of ["read", "bash", "edit", "write", "Agent", "grep"]) {
  const tool = tools.find((item) => item.name === name);
  assert.equal(tool?.alwaysLoad, true, `${name} is alwaysLoad for cache-stable activation`);
}
for (const name of ["TaskOutput", "TaskStop", "TaskList", "find", "ls"]) {
  const tool = tools.find((item) => item.name === name);
  assert.equal(tool?.alwaysLoad, undefined, `${name} is not eager-loaded as a full schema`);
  assert.equal(tool?.deferLoading, true, `${name} stays provider-native deferred`);
}

// replacesBuiltins: each override declares the core base builtin it supersedes so
// the registry drops the lowercase twin (no duplicate Read/read schemas). Consumed
// by AgentSession._refreshToolRegistry in pi-mono-fork core.
const expectedReplacements = {
  read: ["read"],
  bash: ["bash", "Bash"],
  edit: ["edit"],
  write: ["write"],
  grep: ["grep"],
  find: ["find"],
  ls: ["ls"],
  TaskOutput: ["bash_output"],
  TaskStop: ["bash_kill"],
};
for (const [name, replaced] of Object.entries(expectedReplacements)) {
  const tool = tools.find((item) => item.name === name);
  assert.deepEqual(tool?.replacesBuiltins, replaced, `${name} replaces core builtin ${replaced.join(",")}`);
}
// New capabilities with no lowercase base twin must not claim a replacement.
for (const name of ["TaskList", "Agent", "web_fetch", "web_search"]) {
  const tool = tools.find((item) => item.name === name);
  assert.equal(tool?.replacesBuiltins, undefined, `${name} declares no base-builtin replacement`);
}

assert.equal(typeof disposeHandler, "function", "background job store registers a dispose handler");

for (const name of ["web_fetch", "web_search"]) {
  const tool = tools.find((item) => item.name === name);
  assert.deepEqual(tool?.providers, ["claude-bridge"], `${name} is claude-bridge only`);
}

// Edit numbered-pair repair: model crams extra replacements as oldText2/newText2 etc.
const editTool = tools.find((tool) => tool.name === "edit");
assert.equal(typeof editTool?.prepareArguments, "function", "Edit has prepareArguments override");
assert.deepEqual(
  editTool.prepareArguments({ path: "f.txt", oldText: "a", newText: "b", oldText2: "c", newText2: "d" }),
  { path: "f.txt", edits: [{ oldText: "a", newText: "b" }, { oldText: "c", newText: "d" }] },
  "folds oldText/newText + oldText2/newText2 into edits[]",
);
assert.deepEqual(
  editTool.prepareArguments({ path: "f.txt", edits: [{ oldText: "a", newText: "b" }], oldText2: "c", newText2: "d" }),
  { path: "f.txt", edits: [{ oldText: "a", newText: "b" }, { oldText: "c", newText: "d" }] },
  "appends numbered siblings after existing edits[]",
);
assert.deepEqual(
  editTool.prepareArguments({ path: "f.txt", edits: [{ oldText: "a", newText: "b" }] }),
  { path: "f.txt", edits: [{ oldText: "a", newText: "b" }] },
  "valid edits[] input passes through unchanged",
);

console.log(`pi-native-tool-overrides smoke test passed (${tools.length} tools)`);

