	// Claude/Codex-style backgrounding: output updates the UI/log, but does not
	// inject steering messages into the active agent loop. This prevents a log
	// tail or watcher from waking the model on every batch and causing the
	// "waited for background terminal" ping-pong Luke reported.
	safeNotify(activeCtx, `monitor ${m.description}: ${lines.length} new line${lines.length !== 1 ? "s" : ""} · ${m.logPath}`);
