parameters: Type.Object({
	command: Type.String({
		description: "Shell command to monitor via /bin/sh -c. Keep polling intervals inside the command when watching external state, e.g. 'while ...; do ...; sleep 30; done'.",
	}),
	description: Type.String({
		description: "Short human label, e.g. 'vite dev server', 'tail app errors', 'poll CI status'.",
	}),
	cwd: Type.Optional(
		Type.String({ description: "Working directory (default: session cwd)" }),
	),
	triggerOnOutput: Type.Optional(
		Type.Boolean({
			description: "Wake/steer the agent when new output arrives. Use true only when the agent must react immediately to matching output, CI changes, errors, or watcher events. Leave false for noisy dev servers/log tails you will inspect manually.",
		}),
	),
	triggerOnExit: Type.Optional(
		Type.Boolean({
			description: "Wake the agent when the process exits. Default true; set false for pure tails/watchers that are expected to run until stopped.",
		}),
	),
	maxWakeups: Type.Optional(
		Type.Number({
			description: "Maximum output-triggered agent wakeups before output wakes are disabled (default 20, max 100). Does not affect final exit wake.",
		}),
	),
	maxRuntimeSeconds: Type.Optional(
		Type.Number({
			description: "Maximum runtime before the monitor is stopped (default 3600, max 43200). Use a smaller cap for CI/log watches.",
		}),
	),
}),

