  const eagerCapabilities = new Set(eagerTools.map((tool) => normalizeToolName(String(tool.name))));
  const deferredCapabilities = parseDeferredTools(messages0).map(normalizeToolName);
  const duplicateCapabilities = [...new Set(deferredCapabilities.filter((name) => eagerCapabilities.has(name)))].sort();
  const availableSkills = extractBlock(messages0, "available_skills");
  const payloadBytes = Buffer.byteLength(JSON.stringify(dump));

  return {
    estTotalTokens: Math.floor(payloadBytes / 4),
    activeToolCount: activeTools.length,
    eagerToolCount: eagerTools.length,
    nativeDeferredToolCount: tools.filter((tool) => tool.defer_loading === true).length,
    duplicateCapabilities,
    inlineSkillBodyHits: (messages0.match(/^# SKILL\b|^# Skill\b/gm) ?? []).length,
    multilineSkillBlocks: countMultilineSkillBlocks(messages0),
    availableSkillsBytes: Buffer.byteLength(availableSkills),
    systemContextPresent: messages0.includes("<system-context>"),
    messages0HasCacheControl: Array.isArray(messages0Content)
      ? messages0Content.some((block) => block?.cache_control)
      : false,
    systemHasCacheControl: Array.isArray(dump.system)
      ? dump.system.some((block) => block?.cache_control)
      : false,
  };
}

export function promptHealthWarnings(audit, thresholds = PROMPT_HEALTH_THRESHOLDS) {
  const warnings = [];
  const maxEagerTools = thresholds.maxEagerTools ?? thresholds.maxActiveTools;
  if (audit.estTotalTokens > thresholds.maxTotalPromptTokens) {
    warnings.push("total_prompt_over_soft_cap");
  }
  if (audit.eagerToolCount > maxEagerTools) {
    warnings.push("eager_tool_schema_budget_exceeded");
  }
  if (audit.duplicateCapabilities.length > 0) {
    warnings.push("active_deferred_double_billing");
  }
  if (audit.nativeDeferredToolCount === 0 && audit.eagerToolCount > 5) {
    warnings.push("native_deferred_missing");
  }
  if (audit.inlineSkillBodyHits > 0 || audit.multilineSkillBlocks > 0) {
    warnings.push("inline_skill_body");
  }
  if (audit.availableSkillsBytes > thresholds.maxAvailableSkillsBytes) {
    warnings.push("available_skills_over_budget");
  }
  if (audit.systemContextPresent && !audit.messages0HasCacheControl) {
    warnings.push("system_context_missing_cache_control");
  }
  return warnings;
}

export function messageContentText(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content.map((block) => typeof block === "string" ? block : block?.text ?? "").join("\n");
  }
  return "";
}

