const attempts = Number.parseInt(process.env.PI_PROMPT_HEALTH_ATTEMPTS || "3", 10);
const timeoutMs = Number.parseInt(process.env.PI_PROMPT_HEALTH_TIMEOUT_MS || "120000", 10);
const pollMs = Number.parseInt(process.env.PI_PROMPT_HEALTH_POLL_MS || "500", 10);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Run `pi -p` but don't depend on it exiting: it writes the dump before the
// response settles, and one-shot print mode can keep a provider keep-alive
// socket open. Poll for a fresh dump that matches our marker, then kill pi.
async function runAndCaptureDump(startedAt) {
  // stdin must be /dev/null: pi reads piped stdin to EOF when stdin is not a
  // TTY, so an open pipe would make it block forever waiting for input.
  const child = spawn(
    command,
    ["--no-session", "--model", model, "--thinking", "off", "-p", prompt],
    { stdio: ["ignore", "pipe", "pipe"] },
  );
  child.stdout?.setEncoding("utf8");
  child.stderr?.setEncoding("utf8");
  let stdout = "";
  let stderr = "";
  child.stdout?.on("data", (c) => { stdout += c; });
  child.stderr?.on("data", (c) => { stderr += c; });
  let exited = false;
  child.on("exit", () => { exited = true; });

  const deadline = startedAt + timeoutMs;
  try {
    while (Date.now() < deadline) {
      if (existsSync(dumpPath)) {
        const st = statSync(dumpPath);
        if (st.mtimeMs >= startedAt - 1000) {
          const text = readFileSync(dumpPath, "utf8");
          if (text.includes(marker)) return { stdout, stderr, dumpText: text, dumpStat: st };
        }
      }
      if (exited && child.exitCode !== 0) {
        return { stdout, stderr, error: "pi_command_failed", status: child.exitCode };
      }
      await sleep(pollMs);
    }
    return { stdout, stderr, error: "timeout_waiting_for_dump" };
  } finally {
    if (!exited) child.kill("SIGKILL");

