import assert from "node:assert/strict";
import test from "node:test";
import {
  auditPromptDump,
  PROMPT_HEALTH_THRESHOLDS,
  promptHealthWarnings,
} from "./support/prompt-health-audit.mjs";

test("accepts a cache-stable prompt-health fixture", () => {
  const dump = {
    system: "You are Claude Code",
    messages: [
      {
        role: "user",
        content: [
          "<available_skills>",
          "- planning: route planning work",
          "- code-review: review diffs",
          "</available_skills>",
          "<deferred-tools>",
          "- screenshot: capture UI",
          "- click: click UI",
          "</deferred-tools>",
        ].join("\n"),
      },
    ],
    tools: [
      { name: "Bash" },
      { name: "Read" },
      { name: "tool_search" },
      { name: "mcp__pi__monitor_start", defer_loading: true },
    ],
  };

  const audit = auditPromptDump(dump);

  assert.equal(audit.eagerToolCount <= PROMPT_HEALTH_THRESHOLDS.maxEagerTools, true);
  assert.equal(audit.estTotalTokens <= PROMPT_HEALTH_THRESHOLDS.maxTotalPromptTokens, true);
  assert.equal(audit.availableSkillsBytes <= PROMPT_HEALTH_THRESHOLDS.maxAvailableSkillsBytes, true);
  assert.equal(audit.eagerToolCount, 3);
  assert.equal(audit.nativeDeferredToolCount, 1);
  assert.deepEqual(audit.duplicateCapabilities, []);
  assert.equal(audit.inlineSkillBodyHits, 0);
  assert.equal(audit.multilineSkillBlocks, 0);
  assert.deepEqual(promptHealthWarnings(audit), []);
});

test("requires cache_control on moved messages[0] system-context", () => {
  const staleShape = {
    system: [{ type: "text", text: "You are Claude Code", cache_control: { type: "ephemeral", ttl: "1h" } }],
    messages: [
      {
        role: "user",
        content: "<system-context>\nPi real system prompt\n</system-context>",
      },
    ],
    tools: [{ name: "Read" }],
  };
  const fixedShape = {
    system: [{ type: "text", text: "You are Claude Code" }],
    messages: [
      {
        role: "user",
        content: [
          {
            type: "text",
            text: "<system-context>\nPi real system prompt\n</system-context>",
            cache_control: { type: "ephemeral", ttl: "1h" },
          },
        ],
      },
    ],
    tools: [{ name: "Read" }],
  };

  assert.equal(auditPromptDump(staleShape).systemHasCacheControl, true);
  assert.equal(auditPromptDump(staleShape).messages0HasCacheControl, false);
  assert.ok(promptHealthWarnings(auditPromptDump(staleShape)).includes("system_context_missing_cache_control"));
  assert.equal(auditPromptDump(fixedShape).systemHasCacheControl, false);
  assert.equal(auditPromptDump(fixedShape).messages0HasCacheControl, true);
  assert.deepEqual(promptHealthWarnings(auditPromptDump(fixedShape)), []);
});

